def get_smtuserid():
    """Get smt userid.

    If CONF.zvm.smtuserid is set, return it.
    Otherwise, return the first userid in the smt userid list.
    """
    if CONF.zvm.smtuserid:
        return CONF.zvm.smtuserid
    else:
        return CONF.zvm.smtuserid_list[0]


